SELECT jsonb_build_object(
'observed_at',clock_timestamp(),'identity',current_user,'session_user',session_user,'database',current_database(),'version',current_setting('server_version'),
'workspace_schemas',(SELECT coalesce(jsonb_agg(nspname),'[]'::jsonb) FROM pg_namespace WHERE nspname IN ('workspace','workspace_private','workspace_auth_bridge','workspace_bootstrap')),
'workspace_roles',(SELECT coalesce(jsonb_agg(rolname),'[]'::jsonb) FROM pg_roles WHERE rolname IN ('ws_owner','ws_runtime','ws_authz_reader','ws_bootstrap_executor','ws_bootstrap_operator','ws_h3_installer')),
'public_ws_functions',(SELECT coalesce(jsonb_agg(p.oid::regprocedure::text),'[]'::jsonb) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND left(p.proname,3)='ws_'),
'public_ws_relations',(SELECT coalesce(jsonb_agg(relname),'[]'::jsonb) FROM pg_class WHERE relnamespace='public'::regnamespace AND left(relname,3)='ws_'),
'public_ws_types',(SELECT coalesce(jsonb_agg(typname),'[]'::jsonb) FROM pg_type WHERE typnamespace='public'::regnamespace AND left(typname,3)='ws_'),
'public_baseline',jsonb_build_object('tables',(SELECT count(*) FROM pg_class WHERE relnamespace='public'::regnamespace AND relkind='r'),'policies',(SELECT count(*) FROM pg_policies WHERE schemaname='public'),'definers',(SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND prosecdef),'function_hash',(SELECT md5(string_agg(p.oid::regprocedure::text||md5(pg_get_functiondef(p.oid)),'|' ORDER BY p.oid::regprocedure::text)) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.prokind='f')),
'installer',jsonb_build_object('super',(SELECT rolsuper FROM pg_roles WHERE rolname=current_user),'bypass',(SELECT rolbypassrls FROM pg_roles WHERE rolname=current_user),'createrole',(SELECT rolcreaterole FROM pg_roles WHERE rolname=current_user),'db_create',has_database_privilege(current_user,current_database(),'CREATE'),'public_create_grant',has_schema_privilege(current_user,'public','CREATE WITH GRANT OPTION'),'auth_create',has_schema_privilege(current_user,'auth','CREATE'),'auth_owner_set',pg_has_role(current_user,'supabase_auth_admin','SET'),'auth_usage',has_schema_privilege(current_user,'auth','USAGE'),'users_id_references',has_column_privilege(current_user,'auth.users','id','REFERENCES'),'uid_execute',has_function_privilege(current_user,'auth.uid()','EXECUTE'),'jwt_execute',has_function_privilege(current_user,'auth.jwt()','EXECUTE')),
'auth_sessions_columns',(SELECT jsonb_agg(jsonb_build_object('column',a.attname,'type',format_type(a.atttypid,a.atttypmod),'installer_select',has_column_privilege(current_user,a.attrelid,a.attnum,'SELECT'))) FROM pg_attribute a WHERE a.attrelid='auth.sessions'::regclass AND a.attname IN ('id','user_id','created_at','not_after')),
'auth_tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'authenticated_select',has_table_privilege('authenticated',c.oid,'SELECT'),'anon_select',has_table_privilege('anon',c.oid,'SELECT'))) FROM pg_class c WHERE c.oid IN ('auth.users'::regclass,'auth.sessions'::regclass)),
'public_creator_defaults',(SELECT jsonb_agg(jsonb_build_object('type',defaclobjtype,'acl',defaclacl::text)) FROM pg_default_acl WHERE defaclrole=(SELECT oid FROM pg_roles WHERE rolname='postgres') AND defaclnamespace='public'::regnamespace)
) AS gate_metadata;
